import{_ as e,o as a,c as o,a0 as d}from"./chunks/framework.DzvPB4Y-.js";const _=JSON.parse('{"title":"共享资源、缺货与联合模型","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/network/business-scenario.md","filePath":"zh-cn/frameworks/network/business-scenario.md"}'),r={name:"zh-cn/frameworks/network/business-scenario.md"};function c(i,t,l,n,s,h){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="共享资源、缺货与联合模型" tabindex="-1">共享资源、缺货与联合模型 <a class="header-anchor" href="#共享资源、缺货与联合模型" aria-label="Permalink to &quot;共享资源、缺货与联合模型&quot;">​</a></h1><p>完成<a href="./first-flow.html">第一次网络流优化</a>后，先加入一个网络外的容量，再决定是否允许缺货。弧容量充分、图上连通，不代表整个业务有可行解。</p><h2 id="_1-一个共享装卸资源让问题不可行" tabindex="-1">1. 一个共享装卸资源让问题不可行 <a class="header-anchor" href="#_1-一个共享装卸资源让问题不可行" aria-label="Permalink to &quot;1. 一个共享装卸资源让问题不可行&quot;">​</a></h2><p>供给点 a 有 2 kg，需求点 b 需要 2 kg，只有弧 a→b，弧容量为 3 kg。增加共享资源 dock，容量为 1 kg，每运输 1 kg 占用 dock 的 1 kg 容量。</p><p>弧本身能送 2 kg，但 dock 只能支持 1 kg，所以硬需求不可行。增加另一条弧也不一定有用：若它仍消耗同一个 dock，资源总上界没有变化。恢复可行性需要增加资源容量、改变实际路径资源消耗，或经过授权放松需求。</p><p>从第一课的流问题开始，保持供需不变，只增加共享资源行；重新求解后核对流量与资源消耗，而不是手动给提取器填一个方案。</p><h2 id="_2-多商品必须先转换资源占用单位" tabindex="-1">2. 多商品必须先转换资源占用单位 <a class="header-anchor" href="#_2-多商品必须先转换资源占用单位" aria-label="Permalink to &quot;2. 多商品必须先转换资源占用单位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>Kotlin</th><th>Rust</th></tr></thead><tbody><tr><td>共享资源</td><td><code>FlowCapacity</code></td><td><code>FlowResource</code></td></tr><tr><td>商品-弧占用</td><td><code>FlowKey</code> 对应 usage</td><td>consumptions 中的商品/弧键</td></tr><tr><td>商品可用弧</td><td><code>allowedArcs</code></td><td><code>allowed_arcs</code></td></tr><tr><td>弹性供需</td><td><code>FlowSlack</code></td><td><code>FlowBalanceSlack</code></td></tr></tbody></table><p>商品以 kg、m、件计量时，需通过“资源单位/商品单位”的系数换算后求和。不能把归一化整数步数直接当物理占用；也不能将不同 ID 的平行服务合并。</p><h2 id="_3-允许缺货必须同时有上界和费用" tabindex="-1">3. 允许缺货必须同时有上界和费用 <a class="header-anchor" href="#_3-允许缺货必须同时有上界和费用" aria-label="Permalink to &quot;3. 允许缺货必须同时有上界和费用&quot;">​</a></h2><p>单独构造一个带弃供与缺货的场景，数值使用同一归一化单位：</p><table tabindex="0"><thead><tr><th>条件</th><th>数值</th></tr></thead><tbody><tr><td>a 供应 / b 需求</td><td>3 / 4</td></tr><tr><td>弧最大流量 / 单位运输费</td><td>2 / 1</td></tr><tr><td>a 允许未使用供应 / 单位罚费</td><td>最多 1 / 5</td></tr><tr><td>b 允许未满足需求 / 单位罚费</td><td>最多 2 / 7</td></tr></tbody></table><p>流量为 2，未使用供应为 1，缺货为 2，总费用 <code>2×1 + 1×5 + 2×7 = 21</code>。缺货不等于把订单从 4 改成 2，原需求仍需报告；放松的上界也不是无限。</p><p>无论使用哪种语言，验收时都应分别展示实际运输量、弃供、缺货与各项费用。费用相同的不同输入，不是业务结果相同。</p><h2 id="_4-联合模型怎样接线" tabindex="-1">4. 联合模型怎样接线？ <a class="header-anchor" href="#_4-联合模型怎样接线" aria-label="Permalink to &quot;4. 联合模型怎样接线？&quot;">​</a></h2><p>独立入口为 Kotlin <code>NetworkFlowApplicationService</code>、Rust <code>FlowApplicationService</code>。如果流量还要与建线、排程或共享预算一起决策，应把 <code>FlowContext</code> 注册到共同模型，由上层统一求解。</p><p>共享 ID 还不够：相互影响的决策必须通过实际变量、约束或表达式连接。先单独求最便宜运输、再把结果交给排程器，通常只是分解式业务流程，不能声称联合最优。若采用分解算法，需要明确反馈、可行性修复和终止证据。</p><p>复用模型时还需维护 context 与变量映射，不能把上次运行的向量按旧下标填入新模型。建模与执行状态按请求隔离，异常后不继续使用半注册状态。</p><h2 id="_5-验收与练习" tabindex="-1">5. 验收与练习 <a class="header-anchor" href="#_5-验收与练习" aria-label="Permalink to &quot;5. 验收与练习&quot;">​</a></h2><ol><li>将 dock 上界从 1 增到 2，确认硬需求恢复可行；再增到 3，检查是否仍只运输需求 2。</li><li>保持原始硬需求，显式加入有界缺货，再把缺货上界收紧到不足以弥补容量缺口，确认重新不可行。</li><li>逐商品核对守恒、弧上下界、共享资源和松弛；分别重算运输费、未使用供应罚费及缺货罚费。</li><li>在联合模型中修改共享预算，检查网络与另一个领域的决定共同变化，而不是两个互不相关的输出。</li></ol><p>缺货方案能否交付由业务决定，不能只看框架成功返回。按<a href="./../integration.html">接入指南</a>同时保留缺口和真实求解状态；跨地点的时间与人员安排继续到 <a href="./../gantt/business-scenario.html">Gantt</a>。</p><p>源码回归命令统一放在<a href="./../verification.html">仓库验证参考</a>；先完成业务输入、调用与结果复核，再按需验证。</p>',22)])])}const b=e(r,[["render",c]]);export{_ as __pageData,b as default};
